import React from "react";

export default function Scorebelow70({ players }) {
  const players70 = [];
  players.map((item) => {
    if (item.score <= 70) {
      players70.push(item);
    }
    return null;
  });
  return (
    <div>
      {players70.map((p, i) => (
        <li key={i}>Mr. {p.name} <span>{p.score}</span></li>
      ))}
    </div>
  );
}
